<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= e($title) ?></title>
<style>body{font-family:Arial,sans-serif;color:#111;margin:0;background:#f3f4f6}.sheet{max-width:820px;margin:20px auto;background:#fff;padding:32px;border:1px solid #ddd}
table{width:100%;border-collapse:collapse;margin-top:16px}th,td{padding:8px;border-bottom:1px solid #e5e7eb;font-size:14px;text-align:left}th.r,td.r{text-align:right}
.top{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.muted{color:#6b7280;font-size:13px}.tot td{border:0}.btn{padding:8px 14px;background:#f59e0b;border:0;border-radius:4px;cursor:pointer;font-weight:bold}
@media print{body{background:#fff}.sheet{border:0;margin:0}.noprint{display:none}}</style></head><body>
<div class="sheet"><div class="noprint" style="text-align:right"><button class="btn" onclick="window.print()">Print / save as PDF</button></div>
<div class="top"><div><h1 style="margin:0">Tax Invoice</h1><div class="muted">Invoice for order <?= e($o['order_no']) ?><br>Date: <?= e(date('j M Y', strtotime($o['created_at']))) ?></div></div>
<div style="text-align:right"><strong><?= e(cfg('shop.seller.name')) ?></strong><div class="muted"><?= e(cfg('shop.seller.address')) ?><br>GSTIN: <?= e(cfg('shop.seller.gstin')) ?></div></div></div>
<div class="top" style="margin-top:20px"><div><strong>Bill to / Ship to</strong><div class="muted"><?= e($o['ship_name']) ?><br><?= e($o['ship_line1']) ?><?= $o['ship_line2'] ? ', ' . e($o['ship_line2']) : '' ?><br><?= e($o['ship_city']) ?>, <?= e($o['ship_state']) ?> - <?= e($o['ship_pincode']) ?><br>Phone: <?= e($o['ship_phone']) ?></div></div>
<div class="muted">Payment: <?= $o['payment_method'] === 'cod' ? 'Cash on Delivery' : 'Online (Razorpay)' ?><br>Payment status: <?= e(status_label($o['payment_status'])) ?><?= $o['razorpay_payment_id'] ? '<br>Ref: ' . e($o['razorpay_payment_id']) : '' ?></div></div>
<table><thead><tr><th>#</th><th>Item</th><th class="r">Qty</th><th class="r">Unit price</th><th class="r">GST %</th><th class="r">GST incl.</th><th class="r">Amount</th></tr></thead><tbody>
<?php foreach ($items as $i => $it): $opts = json_dec($it['options']); ?><tr><td><?= $i + 1 ?></td><td><?= e($it['name']) ?><div class="muted"><?= e($it['sku']) ?><?= $opts ? ' · ' . e(implode(', ', array_map(fn($k, $v) => "$k: $v", array_keys($opts), $opts))) : '' ?></div></td><td class="r"><?= (int)$it['qty'] ?></td><td class="r"><?= e(inr($it['unit_price'])) ?></td><td class="r"><?= e(rtrim(rtrim(number_format((float)$it['gst_rate'], 2), '0'), '.')) ?></td><td class="r"><?= e(inr($it['tax_amount'])) ?></td><td class="r"><?= e(inr($it['unit_price'] * $it['qty'])) ?></td></tr><?php endforeach; ?></tbody></table>
<table style="max-width:340px;margin-left:auto" class="tot"><tr><td>Subtotal</td><td class="r"><?= e(inr($o['subtotal'])) ?></td></tr>
<?php if ($o['coupon_discount'] > 0): ?><tr><td>Coupon <?= e($o['coupon_code']) ?></td><td class="r">− <?= e(inr($o['coupon_discount'])) ?></td></tr><?php endif; ?>
<tr><td>Shipping</td><td class="r"><?= e(inr($o['shipping_fee'])) ?></td></tr><?php if ($o['cod_fee'] > 0): ?><tr><td>COD fee</td><td class="r"><?= e(inr($o['cod_fee'])) ?></td></tr><?php endif; ?>
<tr><td><strong>Total</strong></td><td class="r"><strong><?= e(inr($o['total'])) ?></strong></td></tr><tr><td class="muted">of which GST on items</td><td class="r muted"><?= e(inr($o['tax_amount'])) ?></td></tr></table>
<p class="muted" style="margin-top:24px">Demo store: this sample invoice is illustrative and is not a legal tax document. Prices are inclusive of GST.</p></div></body></html>
